// Reporting queries (Phase 3A). Read-only aggregates over the frozen
// sale.finalized.v1 projection. Every time filter is the half-open window
// [start, end) on sales_projection.occurred_at (business time, never
// transport time). Money aggregates cast numeric SUM to bigint so overflow
// fails explicitly instead of wrapping or floating. No dynamic SQL: one
// static query per report need; currency ” means all currencies (bucketed,
// never summed across currencies).
func (q *Queries) ReportSalesSummary(ctx context.Context, arg ReportSalesSummaryParams) ([]ReportSalesSummaryRow, error) {
	rows, err := q.db.Query(ctx, reportSalesSummary, arg.StartUtc, arg.EndUtc, arg.Currency)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReportSalesSummaryRow{}
	for rows.Next() {
		var i ReportSalesSummaryRow
		if err := rows.Scan(
			&i.Currency,
			&i.Transactions,
			&i.Subtotal,
			&i.Discount,
			&i.Tax,
			&i.SalesTotal,
			&i.Units,
			&i.LineCost,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

